el('focusMode').onchange=()=>projectAction('focus',{value:el('focusMode').checked});
el('syncHighlight').onchange=()=>projectAction('syncHighlight',{value:el('syncHighlight').checked});
el('autoAdvance').onchange=()=>projectAction('autoAdvance',{value:el('autoAdvance').checked});
el('languageMode').onchange=()=>{command('stop');projectAction('language',{value:el('languageMode').value});};
el('savePronunciations').onclick=()=>projectAction('pronunciation',{text:el('pronunciations').value});
el('saveCorrection').onclick=()=>{command('stop');projectAction('correctSource',{text:el('sourceCorrection').value});};
el('askAI').onclick=()=>{command('stop');el('aiAnswer').textContent='Preparing local inference…';projectAction('ai',{task:el('aiTask').value,question:el('aiQuestion').value});};
el('focusBookmark').onclick=()=>el('bookmark').click();
el('goStructure').onclick=()=>{const line=Number(el('structures').value);if(Number.isInteger(line)){command('stop');projectAction('structure',{line});}};
function showPassages(m){if(!m.passages)return;const target=el('passages'),scroll=target.scrollTop;target.replaceChildren();for(const passage of m.passages){const button=document.createElement('button');button.textContent=passage.text;button.setAttribute('aria-current',String(passage.index===m.index));button.onclick=()=>command('jump',{index:passage.index});target.append(button);}target.scrollTop=scroll;}
